CREATE TABLE IF NOT EXISTS scale_meta(key text PRIMARY KEY,value jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS companies(tenant_id text PRIMARY KEY,company_name text NOT NULL,industry text NOT NULL,registered_city text NOT NULL,created_at date NOT NULL);
CREATE TABLE IF NOT EXISTS departments(tenant_id text NOT NULL,department_id text NOT NULL,name text NOT NULL,parent_department_id text,manager_employee_id text NOT NULL,cost_center text NOT NULL,PRIMARY KEY(tenant_id,department_id));
CREATE TABLE IF NOT EXISTS employees(tenant_id text NOT NULL,employee_id text NOT NULL,seed_no integer NOT NULL UNIQUE,employee_name text NOT NULL,department_id text NOT NULL,job_title text NOT NULL,employment_status text NOT NULL,hire_date date NOT NULL,birth_date date NOT NULL,email text NOT NULL,phone text NOT NULL,bank_account text NOT NULL,address text NOT NULL,PRIMARY KEY(tenant_id,employee_id));
CREATE INDEX IF NOT EXISTS employees_department_idx ON employees(tenant_id,department_id,employee_id);
CREATE TABLE IF NOT EXISTS contracts(tenant_id text NOT NULL,contract_id text NOT NULL,employee_id text NOT NULL,department_id text NOT NULL,start_date date NOT NULL,end_date date NOT NULL,contract_type text NOT NULL,base_salary numeric(12,2) NOT NULL,work_location text NOT NULL,terms_summary text NOT NULL,PRIMARY KEY(tenant_id,contract_id),UNIQUE(tenant_id,employee_id));
CREATE TABLE IF NOT EXISTS payroll(tenant_id text NOT NULL,employee_id text NOT NULL,employee_name text NOT NULL,department_id text NOT NULL,month text NOT NULL,base numeric(12,2) NOT NULL,bonus numeric(12,2) NOT NULL,overtime_pay numeric(12,2) NOT NULL,total numeric(12,2) NOT NULL,social_insurance numeric(12,2) NOT NULL,tax numeric(12,2) NOT NULL,net_pay numeric(12,2) NOT NULL,bank_account text NOT NULL,payment_status text NOT NULL,payment_date date NOT NULL,payroll_note text NOT NULL,PRIMARY KEY(tenant_id,employee_id,month));
CREATE INDEX IF NOT EXISTS payroll_department_month_idx ON payroll(tenant_id,department_id,month DESC);
CREATE TABLE IF NOT EXISTS attendance(tenant_id text NOT NULL,employee_id text NOT NULL,department_id text NOT NULL,work_date date NOT NULL,shift_code text NOT NULL,clock_in timestamp,clock_out timestamp,work_minutes integer NOT NULL CHECK(work_minutes BETWEEN 0 AND 1440),overtime_minutes integer NOT NULL CHECK(overtime_minutes BETWEEN 0 AND 720),status text NOT NULL,work_site text NOT NULL,note text NOT NULL,PRIMARY KEY(tenant_id,employee_id,work_date));
CREATE INDEX IF NOT EXISTS attendance_department_date_idx ON attendance(tenant_id,department_id,work_date DESC);
CREATE TABLE IF NOT EXISTS leave_requests(tenant_id text NOT NULL,leave_id text NOT NULL,employee_id text NOT NULL,department_id text NOT NULL,start_date date NOT NULL,end_date date NOT NULL,days numeric(5,1) NOT NULL,leave_type text NOT NULL,status text NOT NULL,approver_employee_id text NOT NULL,reason text NOT NULL,PRIMARY KEY(tenant_id,leave_id),CHECK(end_date>=start_date));
CREATE INDEX IF NOT EXISTS leave_employee_date_idx ON leave_requests(tenant_id,employee_id,start_date DESC);
